n_epochs = 80
policy_updates_per_epoch = 5

x_range = np.arange(n_epochs) * policy_updates_per_epoch


def make_plot(xlabel, ylabel, dictkey, figname, labels, results_list, n_epochs, color_list, linestyle_list, avg_result=False):
    plt.clf()
    plt.xlabel(xlabel)
    plt.ylabel(ylabel)

    for i in range(len(labels)):
        dict_list = results_list[i]
        results = []
        for d in dict_list:
            to_append = np.array(d[dictkey][:n_epochs])
            if avg_result:
                to_append = np.stack(to_append).mean(-1)
            results.append(to_append)

        for x in results:
            print(x.shape)

        to_plot = np.stack(results)
        # print(to_plot.shape)

        last, conf_bound = plot_with_conf_bounds(
            np.array(to_plot),
            x_range,
            label=labels[i],
            color=color_list[i],
            linestyle=linestyle_list[i],
        )

    # plt.legend(loc='upper right', bbox_to_anchor=(1, 0.6), fontsize=7)
    plt.legend()
    plt.savefig(figname)

def make_frontier(xlabel, ylabel, dictkey_x, dictkey_y, figname, labels, results_list, n_epochs, color_list, marker_list, xlimlow=None, xlimhigh=None, fontsize=7):
    plt.clf()
    plt.xlabel(xlabel)
    plt.ylabel(ylabel)

    for i in range(len(labels)):
        print(labels[i])
        dict_list = results_list[i]
        x_results = []
        y_results = []
        for d in dict_list:
            # Take last result
            x_results.append(np.array(d[dictkey_x][n_epochs - 1]))
            y_results.append(np.array(d[dictkey_y][n_epochs - 1]))

        to_plot_x = np.stack(x_results)
        to_plot_y = np.stack(y_results)

        # print(to_plot.shape)

        plt.scatter(to_plot_x, to_plot_y, label=labels[i], c=color_list[i], marker=marker_list[i])

    if (xlimlow is not None) or (xlimhigh is not None):
        plt.xlim(xlimlow, xlimhigh)
    # plt.legend(loc='upper right', bbox_to_anchor=(1, 0.6), fontsize=7)
    plt.legend(fontsize=fontsize)
    plt.savefig(figname)

